    rader=[(r[0],[Vector((r[1+3*i]/1000,r[2+3*i]/1000,r[3+3*i]/1000)) for i in range(len(L))]) for sp in spar for r in sp["rutor"]]
    rader.sort(key=lambda x:x[0]); U=[u for u,_ in rader]; ref=rader[0][1]
